// Resolve flex-grow / flex-shrink widths by hand (no min/max clamping)
function resolve(container, items) {
  const sumBasis = items.reduce((s, i) => s + i.basis, 0);
  const free = container - sumBasis; // positive: grow, negative: shrink
  let weights;
  if (free >= 0) {
    const g = items.reduce((s, i) => s + i.grow, 0);
    const share = g < 1 ? g : 1; // grow sum below 1 hands out only a fraction
    return items.map(i => i.basis + (g ? free * share * i.grow / g : 0));
  }
  // shrink is weighted by shrink * basis
  weights = items.map(i => i.shrink * i.basis);
  const wsum = weights.reduce((s, w) => s + w, 0);
  return items.map((i, k) => i.basis + free * weights[k] / wsum);
}
