// Which element wins? Compare z-index at the first shared stacking context.
const nodes = {
  root:    { parent: null,     ctx: true,  z: 0 },
  header:  { parent: 'root',   ctx: true,  z: 1 },    // e.g. has transform
  modal:   { parent: 'header', ctx: true,  z: 9999 },
  content: { parent: 'root',   ctx: true,  z: 5 },
};
// chain of context-creating nodes from the root down to the element
function chain(name) {
  const out = [];
  for (let n = name; n; n = nodes[n].parent) if (nodes[n].ctx) out.unshift(n);
  return out;
}
function winner(a, b) {
  const ca = chain(a), cb = chain(b);
  let i = 0;
  while (ca[i] === cb[i]) i++; // first level where the chains differ
  const x = ca[i], y = cb[i];
  console.log(a + ' is represented by ' + x + ' (z=' + nodes[x].z + ')');
  console.log(b + ' is represented by ' + y + ' (z=' + nodes[y].z + ')');
  return nodes[x].z > nodes[y].z ? a : b;
}
console.log('modal z=9999 inside header z=1, content z=5');
console.log('on top: ' + winner('modal', 'content'));

