// How many columns does repeat(auto-fit, minmax(min(220px,100%), 1fr)) make?
function columns(width, min, gap) {
  const m = Math.min(min, width);            // min(220px, 100%)
  const n = Math.max(1, Math.floor((width + gap) / (m + gap)));
  const col = (width - (n - 1) * gap) / n;   // 1fr shares the leftover space
  return { n, col };
}
const min = 220, gap = 16;
[200, 320, 600, 900, 1280].forEach(w => {
  const r = columns(w, min, gap);
  console.log('container ' + w + 'px -> ' + r.n + ' column(s) of ' + r.col.toFixed(1) + 'px');
});
