// Theme resolution: explicit user choice beats the OS preference
const tokens = {
  light: { '--color-bg': '#ffffff', '--color-text': '#111111' },
  dark:  { '--color-bg': '#121212', '--color-text': '#eeeeee' },
};
function pickTheme(userChoice, osPrefersDark) {
  // mirrors :root[data-theme] and @media guarded by :root:not([data-theme="light"])
  if (userChoice === 'light' || userChoice === 'dark') return userChoice;
  return osPrefersDark ? 'dark' : 'light';
}
// semantic tokens: components only ever read var(--color-bg), never a hex
function render(theme) {
  const t = tokens[theme];
  return 'background ' + t['--color-bg'] + ', text ' + t['--color-text'];
}
const cases = [[null, false], [null, true], ['light', true], ['dark', false]];
cases.forEach(c => {
  const th = pickTheme(c[0], c[1]);
  console.log('user=' + c[0] + ' os-dark=' + c[1] + ' -> ' + th + ': ' + render(th));
});
